void AnalogOscillator::RenderTripleMix(
    const uint8_t* sync_in,
    int16_t* __restrict__ buffer,
    uint8_t* sync_out,
    size_t size) {


  if (shape_ != previous_shape_) {
    Init();
    previous_shape_ = shape_;
  }

  phase_increment_ = ComputePhaseIncrement(pitch_);

  if (pitch_ > kHighestNote) {
    pitch_ = kHighestNote;
  } else if (pitch_ < 0) {
    pitch_ = 0;
  }

  // Triple waveforms keep shape-change Init and
  // phase preparation identical to the general renderer.
  switch (shape_) {
    case OSC_SHAPE_SQUARE: RenderSquareTripleMix(sync_in, buffer, sync_out, size); break;
    case OSC_SHAPE_SAW: RenderSawTripleMix(sync_in, buffer, sync_out, size); break;
    default: break;
  }
}
